    "guide.authorBio": "푸저우 공업구 허브의 CAD 설계 엔지니어와 수출 전문가가 작성했습니다. 총 140개 금속 EDC 금형의 NdFeB 자석 배열 보정, 5축 CNC 공차 검증, 50W 파이버 레이저 각인 및 미국 CPSC 16 CFR 1262 / EU RoHS 3 규정 준수를 총괄합니다.",
