    "about.heroDesc": "아연 합금 다이캐스팅, 5축 CNC 가공, 네오디뮴 자석 조립, 레이저/UV 브랜딩 전문 공방 네트워크를 하나로 연결하여 중국 푸젠성 푸저우 수출 물류 허브에서 전 세계로 통합 배송합니다.",
    "about.geoTitle": "중국 금속 EDC 피젯 산업을 연결하는 통합 소싱 및 공급망 플랫폼",
    "about.geoAnswer": "아연 합금 다이캐스팅, 5축 CNC 가공, 네오디뮴 자석 조립, 레이저/UV 브랜딩 전문 공방 네트워크를 하나로 연결하여 중국 푸젠성 푸저우 수출 물류 허브에서 전 세계로 통합 배송합니다. 본 모델은 당사의 검증된 기성 양산 금형을 사용합니다. 무지 도매(MOQ 50개) 또는 파이버 레이저 각인 및 UV 인쇄(MOQ 100개) 주문이 즉시 가능합니다.",
